preConditionHook:
// THE ASCENDING TRIANGLE, which this corpus lacks: over the recent window the
// FLOOR has risen while the CEILING has stayed flat -- buyers holding
// successively higher lows against a stable resistance, Grimes's stated
// precondition for the best upside breakouts. Mirrored, the short side is the
// descending triangle: falling highs pressing into a flat floor.
//
// TWO ADJACENT WINDOWS, not nested: the recent window is bars
// 0..recentBars-1 and the prior window is bars recentBars..recentBars+priorBars-1,
// so the EL twin hands Lowest/Highest the SHIFTED price series (the low series offset by
// recentBars)
// rather than lagging the function's own result (the
// StopBeyondRecentRangeExtreme / TouchOfRecentExtreme spelling).
//
// Not BarsSinceExtremeExceeds, which is the flat-ceiling half ALONE, on NESTED
// current-inclusive windows (inner rangeBars inside outer rangeBars+priorLookback),
// and is MIRRORED -- so one placement gives the highs test or the lows test and
// never both, and the pair of tests this rule ANDs is unreachable from it.
// Not HigherLowCount, which counts bar PAIRS rather than a window floor that
// has risen. Not ChannelWidthConvergence, two sloping pivot lines, which is
// direction-agnostic and so cannot say WHICH side is the flat one.
//
// BOTH BANDS ARE ATR FRACTIONS (merge decision 7), never ticks and never a
// percentage of price, so the whole rule is differences over a difference and
// passes the shift test.
//
// The pseudocode's PIVOT spelling lost to the two-window form at merge: a
// pivot has a confirmation lag and retention, and "the ceiling is roughly
// flat" has no pivot spelling at all.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh mean:
// AtrProfitTarget's block verbatim, including the TWO separate accumulator
// statements, since EasyLanguage evaluates Summation[1] + Price - Price[Length]
// left to right, and the re-seed when the length changes.
//
// The window loops mirror EasyLanguage's Extremes(), which Highest()/Lowest()
// call: seeded at the window's first bar, scanning the rest, strict comparison
// under the EL relational tolerance -- hence el_gt / el_lt, as in Breakout.
//
// Every scratch value is a localVariables entry or a loop-scoped int, never a
// hook-scope declaration, so the hooks survive a double placement.
//
// Deepest bar touched: max(recentBars + priorBars - 1, atrLookback + 1).
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
recLo = low[0];
recHi = high[0];
for (int i = 1; i < (int)recentBars; ++i) {
    if (el_lt(low[i], recLo)) recLo = low[i];
    if (el_gt(high[i], recHi)) recHi = high[i];
}
priLo = low[recentBars];
priHi = high[recentBars];
for (int i = 1; i < (int)priorBars; ++i) {
    if (el_lt(low[(int)recentBars + i], priLo)) priLo = low[(int)recentBars + i];
    if (el_gt(high[(int)recentBars + i], priHi)) priHi = high[(int)recentBars + i];
}
